class Account:
    def __init__(self, balance):
        self.balance = balance
        self.history = []

    def withdraw(self, amount):
        if amount > self.balance:
            raise ValueError("insufficient funds")
        self.balance -= amount
        # audit trail
        self.history.append(amount)
        return self.balance

    @property
    def summary(self):
        return (
            self.balance,
            len(self.history),
        )


def standalone(value):
	if value:
		return value * 2
	return None

