export class Cart {
  constructor(items) {
    this.items = items;
    this.count = items.length;
  }

  async total(tax) {
    let sum = 0;
    for (const item of this.items) {
      sum += item.price * (1 + tax);
    }
    return sum;
  }

  static get empty() {
    return new Cart([]);
  }
}

